import React from "react";

function Section4() {
  const solarSystemPlanets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <div className=" text-white">
       <ol style={{ listStyleType: "decimal" }}>
      {solarSystemPlanets.map((planet, index) => (
        <li key={index}>{index+ ' ' +planet}</li>
      ))}
    </ol>
    </div>
  );
}

export default Section4;
